export function mapIssues(issues: Issue[]): IssueMap {
  const m: IssueMap = { sms: [], emailSubject: [], emailBody: [], segment: [], form: [] }
  for (const i of issues) {
    const field = Object.hasOwn(fields, i.path) ? fields[i.path] : undefined
