var errBadEventID = errors.New("expected a non-negative integer event id")

func parseEventID(s string) (int64, error) {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 {
		return 0, errBadEventID
	}
	return n, nil
}

// Jeton yalnızca yetki başlığından gelir.
func (s *Server) events(w http.ResponseWriter, r *http.Request, id string) {
	var after int64
	for _, raw := range []string{r.URL.Query().Get("after"), r.Header.Get("Last-Event-ID")} {
		if raw == "" {
			continue
		}
		n, err := parseEventID(raw)
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_event_id", err.Error())
			return
		}
		after = max(after, n)
	}
	{
		ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
		_, err := store.GetCampaign(ctx, s.Pool, id)
		cancel()
		if err != nil {
			s.fail(w, r, err)
			return
		}
	}

	var wake <-chan struct{}
	if s.Hub != nil {
		ch, unsubscribe := s.Hub.Subscribe(id)
		defer unsubscribe()
		wake = ch
	}
	rc := http.NewResponseController(w)
	// Sunucunun yazma süresi uzun akışı keserdi.
	_ = rc.SetWriteDeadline(time.Time{})
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)
	if rc.Flush() != nil {
		return
	}

	heartbeat := s.Heartbeat
	if heartbeat <= 0 {
		heartbeat = DefaultHeartbeat
	}
	poll := s.PollInterval
	if poll <= 0 {
		poll = DefaultPollInterval
	}
	hb, pt := time.NewTicker(heartbeat), time.NewTicker(poll)
	defer hb.Stop()
	defer pt.Stop()

	send := func() (bool, error) {
		ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
		defer cancel()
		list, err := store.ListGenerationEvents(ctx, s.Pool, id, after)
		if err != nil {
			return false, err
		}
		for _, e := range list {
			if _, err := fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", e.ID, e.Type, e.Payload); err != nil {
				return false, err
			}
			after = e.ID
			if e.Type == "done" || e.Type == "failed" {
				return true, rc.Flush()
			}
		}
		return false, rc.Flush()
	}
	for {
		ended, err := send()
		if err != nil {
			if r.Context().Err() == nil {
				s.Log.Warn("event stream failed", "error", err, "request_id", requestIDFrom(r.Context()))
			}
			return
		}
		if ended {
			return
		}
	wait:
		select {
		case <-r.Context().Done():
			return
		case <-hb.C:
			if _, err := fmt.Fprint(w, ": heartbeat\n\n"); err != nil || rc.Flush() != nil {
				return
			}
			goto wait
		case <-wake:
		case <-pt.C:
		}
	}
}
CREATE DOMAIN message_state AS text CHECK (VALUE IN (
    'queued', 'sending', 'sent', 'failed', 'dead', 'skipped'));

CREATE DOMAIN error_class AS text CHECK (VALUE IN (
    'rate_limited', 'server_error', 'timeout', 'conn_refused', 'conn_reset',
    'client_error', 'no_consent', 'cancelled'));

CREATE TABLE campaigns (
    id                   uuid           PRIMARY KEY DEFAULT gen_random_uuid(),
    brief                text           NOT NULL CHECK (char_length(brief) BETWEEN 1 AND 2000),
    state                campaign_state NOT NULL DEFAULT 'draft',
    version              integer        NOT NULL DEFAULT 0,
    current_revision_id  uuid,
    approved_revision_id uuid,
    approved_by          text,
    approved_at          timestamptz,
    campaign_url         text           CHECK (char_length(campaign_url) <= 40),
    created_at           timestamptz    NOT NULL DEFAULT now(),
    updated_at           timestamptz    NOT NULL DEFAULT now(),
    CHECK ((approved_revision_id IS NULL) = (approved_by IS NULL)
       AND (approved_revision_id IS NULL) = (approved_at IS NULL)),
}

func (r *statusRecorder) Write(b []byte) (int, error) {
	if r.status == 0 {
		r.status = http.StatusOK
	}
	return r.ResponseWriter.Write(b)
}

func (r *statusRecorder) Hijack() (net.Conn, *bufio.ReadWriter, error) {
	return http.NewResponseController(r.ResponseWriter).Hijack()
}

func (r *statusRecorder) Flush() { _ = http.NewResponseController(r.ResponseWriter).Flush() }

func (r *statusRecorder) Unwrap() http.ResponseWriter { return r.ResponseWriter }

type countingLimiter struct{ n atomic.Int64 }

func (c *countingLimiter) Wait(ctx context.Context) error {
	c.n.Add(1)
	return ctx.Err()
}

var errCrash = errors.New("injected crash: the database is gone")

type flakyDB struct {
	*pgxpool.Pool
	down atomic.Bool
}

func (d *flakyDB) Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error) {
	if d.down.Load() {
		return pgconn.CommandTag{}, errCrash
	}
	return d.Pool.Exec(ctx, sql, args...)
}

func (d *flakyDB) Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error) {
	if d.down.Load() {
		return nil, errCrash
	}
	return d.Pool.Query(ctx, sql, args...)
}

func (d *flakyDB) QueryRow(ctx context.Context, sql string, args ...any) pgx.Row {
	if d.down.Load() {
		return errRow{}
	}
	return d.Pool.QueryRow(ctx, sql, args...)
}

func (d *flakyDB) Begin(ctx context.Context) (pgx.Tx, error) {
	if d.down.Load() {
		return nil, errCrash
	}
	return d.Pool.Begin(ctx)
}

type errRow struct{}

func (errRow) Scan(...any) error { return errCrash }

type sendEnv struct {
	pool    *pgxpool.Pool
	asOf    time.Time
	now     time.Time
	prov    *provider
	tokens  map[string]*countingLimiter
	worker  *SendWorker
	logs    *bytes.Buffer
	retries []int
	mu      sync.Mutex
}

const fixedBackoff = 3 * time.Second

func newSendEnv(t *testing.T, cfg mockprovider.Config) *sendEnv {
	t.Helper()
	pool, meta := appPool(t)
	e := &sendEnv{
		pool:   pool,
		asOf:   meta.AsOf,
		now:    meta.AsOf.Add(time.Hour),
		prov:   newProvider(t, cfg),
		tokens: map[string]*countingLimiter{"sms": {}, "email": {}},
		logs:   &bytes.Buffer{},
	}
	e.worker = &SendWorker{
		DB:              pool,
		ProviderURL:     e.prov.URL,
		Limiters:        map[string]Limiter{"sms": e.tokens["sms"], "email": e.tokens["email"]},
		ProviderTimeout: 300 * time.Millisecond,
		Now:             func() time.Time { return e.now },
		Backoff: func(retry int) time.Duration {
			e.mu.Lock()
			defer e.mu.Unlock()
			e.retries = append(e.retries, retry)
			return fixedBackoff
		},
		Log: slog.New(slog.NewJSONHandler(&lockedWriter{w: e.logs}, &slog.HandlerOptions{Level: slog.LevelDebug})),
	}
	return e
}

type lockedWriter struct {
	mu sync.Mutex
	w  io.Writer
}

func (l *lockedWriter) Write(b []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.w.Write(b)
}

func (e *sendEnv) tokensTaken() int64 { return e.tokens["sms"].n.Load() + e.tokens["email"].n.Load() }

