	stuck := insertCampaignIn(t, pool, "generating", 3)
	insertJob(t, pool, "generate", "discarded", `{"campaign_id":"`+stuck.ID+`","version":3}`)
	// Eski sürümün tükenen işi yeni üretime dokunmamalı.
